#!/usr/bin/env node
// scripts/count-assertions.mjs
//
// Auto-counts every assertion across every test harness in AIECP.
// This is the STRUCTURAL FIX for the "STATUS.md drift" problem:
// if a human has to remember to update counts, the counts WILL go
// stale (proven: 4 cycles of dialogue). This script replaces the
// human with a script that runs the actual commands and parses
// their actual output.
//
// The STATUS.md assertion table is auto-generated by this script.
// DO NOT EDIT the table by hand — run `npm run count-assertions`
// and the table regenerates from real harness output.
//
// ADR context: this script closes the gap surfaced by an external
// critic (2026-08-16) — "is this verification process going to
// stay manual forever? if so, in 2 months you'll have the same
// '56 vs 58' drift again." This script makes the process
// structural, not human-dependent.
//
// Usage:
//   node scripts/count-assertions.mjs            # prints summary + table
//   node scripts/count-assertions.mjs --json     # emits JSON only
//   node scripts/count-assertions.mjs --table    # emits Markdown table only
//   node scripts/count-assertions.mjs --write    # writes the table into STATUS.md

import { spawnSync } from "node:child_process";
import { readdirSync, readFileSync, writeFileSync, existsSync } from "node:fs";
import { join, dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const __dirname = dirname(fileURLToPath(import.meta.url));
const REPO_ROOT = resolve(__dirname, "..");

// ---- harness runners ----
// Each entry: how to invoke, how to parse PASS/FAIL counts from output.

function runEvalRunner() {
  // python3 evaluations/eval_runner.py — emits summary lines like:
  //   "Scenarios:  25/25 passed (0 failed)"
  //   "Assertions: 115/115 passed (0 failed)"
  const pyCmd = process.platform === "win32" ? "python" : "python3";
  let r = spawnSync(
    pyCmd,
    ["evaluations/eval_runner.py"],
    { cwd: REPO_ROOT, encoding: "utf-8" }
  );
  if (r.error && process.platform === "win32") {
    r = spawnSync("python3", ["evaluations/eval_runner.py"], { cwd: REPO_ROOT, encoding: "utf-8" });
  }
  const out = (r.stdout || "") + (r.stderr || "");
  const scenariosLine = out.match(/Scenarios:\s+(\d+)\/(\d+) passed \((\d+) failed\)/);
  const assertionsLine = out.match(/Assertions:\s+(\d+)\/(\d+) passed \((\d+) failed\)/);
  if (!scenariosLine || !assertionsLine) {
    return { pass: 0, fail: 0, scenarios: 0, scenariosPassed: 0, error: "could not parse eval_runner output" };
  }
  return {
    pass: parseInt(assertionsLine[1], 10),
    fail: parseInt(assertionsLine[3], 10),
    scenarios: parseInt(scenariosLine[2], 10),
    scenariosPassed: parseInt(scenariosLine[1], 10),
  };
}

function runNpmSelfTest(workspace) {
  const cliPath = join(REPO_ROOT, workspace, "dist", "cli.js");
  let out = "";
  if (existsSync(cliPath)) {
    const r = spawnSync("node", [cliPath, "--self-test"], { cwd: REPO_ROOT, encoding: "utf-8" });
    out = (r.stdout || "") + (r.stderr || "");
  } else {
    const npmCmd = process.platform === "win32" ? "npm.cmd" : "npm";
    const r = spawnSync(npmCmd, ["test", `--workspace=${workspace}`], { cwd: REPO_ROOT, encoding: "utf-8" });
    out = (r.stdout || "") + (r.stderr || "");
  }
  const allMatches = Array.from(out.matchAll(/Results:\s+(\d+) passed,\s+(\d+) failed/g));
  if (allMatches.length === 0) return { pass: 0, fail: 0, error: "could not parse results line" };
  const lastMatch = allMatches[allMatches.length - 1];
  return { pass: parseInt(lastMatch[1], 10), fail: parseInt(lastMatch[2], 10) };
}

function runE2eDriver(scriptPath) {
  // node executor/examples/e2e-XXX/drive-run.mjs — emits lines like:
  //   "  OK   <label>"  (pass)
  //   "  FAIL <label>"  (fail)
  //   "E2E DRIVER PASSED" or "E2E DRIVER FAILED" (terminal marker)
  //
  // Status detection (per ADR-0029 Q3 follow-up):
  //   - "pass-with-assertions": has OK lines, has "PASSED" marker, no FAIL lines.
  //   - "fail-with-assertions": has FAIL lines (regardless of marker).
  //   - "no-assertions": okCount + failCount == 0. The script may emit
  //     "PASSED" as a narrative marker (e.g. e2e-membership-bug), but
  //     without actual OK/FAIL assertion lines it's a narrative demo,
  //     not a counted test. WARNING is emitted for these so a future
  //     contributor adding a narrative-only script knows the count is
  //     0 and can either add assertions or document why.
  const r = spawnSync(
    "node",
    [scriptPath],
    { cwd: REPO_ROOT, encoding: "utf-8" }
  );
  const out = (r.stdout || "") + (r.stderr || "");
  const okCount = (out.match(/^\s*OK\s/gm) || []).length;
  const failCount = (out.match(/^\s*FAIL\s/gm) || []).length;
  let status;
  if (okCount + failCount === 0) {
    status = "no-assertions";
  } else if (failCount > 0) {
    status = "fail";
  } else {
    status = "pass";
  }
  return { pass: okCount, fail: failCount, status };
}

function runChatValidator(responseFile) {
  // node scripts/validate-chat-output.mjs <file> — emits:
  //   stdout: "=== Results: <pass> passed, <fail> failed (of <total> total) ==="
  //   stderr: "VALIDATION PASSED" or "VALIDATION FAILED"
  //   exit 0 = pass, exit 1 = validator FAIL (intentional for regression fixtures),
  //   exit 2 = harness error (parse/IO/missing file)
  // Use spawnSync to capture stdout and stderr separately, then concat.
  const r = spawnSync(
    "node",
    ["scripts/validate-chat-output.mjs", responseFile],
    { cwd: REPO_ROOT, encoding: "utf-8" }
  );
  const out = (r.stdout || "") + (r.stderr || "");
  const m = out.match(/Results:\s+(\d+) passed,\s+(\d+) failed/);
  if (m) {
    return { pass: parseInt(m[1], 10), fail: parseInt(m[2], 10) };
  }
  // No "Results:" line — either:
  //   (a) bare-aiecp fixture (exit 1, validator rejected format — intentional)
  //   (b) true harness error (exit 2, e.g. file not found)
  // Both produce 0 pass / 0 fail for our purposes. The distinction
  // (intentional vs error) is documented in scripts/test-responses/README.md.
  if (r.status === 1 || r.status === 0) {
    return { pass: 0, fail: 0 };
  }
  return { pass: 0, fail: 0, error: `validator exited ${r.status}` };
}

// ---- orchestration: run everything, collect results ----

function collectAll() {
  const components = [];

  // 1. eval_runner.py — discovers scenarios/ via its own glob, so new
  //    scenario files are picked up automatically.
  try {
    const r = runEvalRunner();
    if (r.error) {
      // r.error means the subprocess ran but its output couldn't be parsed
      // (e.g. a crash before it printed a summary line, or a missing build
      // step — see evaluations/README.md prerequisites). Reporting this as
      // silent "0/0 PASS" would look identical to "no tests exist", which
      // is exactly the kind of masked failure ADR-0029 Q3 already fixed
      // for e2e drivers. Surface it the same way: WARNING to stderr, and
      // the error text (not a fake pass count) in the table's notes column.
      process.stderr.write(
        `WARNING: eval_runner.py output could not be parsed (${r.error}) — ` +
        `reporting 0 pass/0 fail, which may mask real failures rather than ` +
        `mean no tests exist. Run \`python3 evaluations/eval_runner.py\` ` +
        `directly to see the actual error.\n`
      );
    }
    components.push({
      name: "eval_runner.py",
      kind: "eval-runner",
      cmd: "python3 evaluations/eval_runner.py",
      ...r,
      notes: r.error ? `ERROR: ${r.error}` : `${r.scenariosPassed}/${r.scenarios} scenarios PASS`,
    });
  } catch (e) {
    process.stderr.write(`WARNING: eval_runner.py could not be run at all (${e.message.slice(0, 100)}) — reporting 0 pass/0 fail.\n`);
    components.push({ name: "eval_runner.py", cmd: "python3 evaluations/eval_runner.py", pass: 0, fail: 0, notes: `ERROR: ${e.message.slice(0, 100)}` });
  }

  // 2. npm workspace self-tests — discover workspaces from package.json
  //    so a new workspace added to "workspaces" array is picked up
  //    automatically without editing this script. (Previously hardcoded
  //    to ["executor", "adapters/agents"] — see ADR-0029 Q2 follow-up.)
  const pkgJson = JSON.parse(readFileSync(join(REPO_ROOT, "package.json"), "utf-8"));
  const workspaces = pkgJson.workspaces || [];
  for (const ws of workspaces) {
    // Skip discovery/cli — it has no --self-test entrypoint (its tests
    // are run via its own `npm test`, which emits a different output
    // format not parseable by our regex). If discovery/cli ever gains
    // a --self-test, this skip can be removed.
    if (ws === "discovery/cli") continue;
    try {
      const r = runNpmSelfTest(ws);
      if (r.error) {
        // Same masking risk as the eval_runner case above: a workspace
        // that fails to build/run (e.g. `npm install` or `npm run build`
        // not yet done — see CONTRIBUTING.md / evaluations/README.md
        // prerequisites) reports 0/0 here, which looks identical to
        // "this workspace legitimately has no tests." Surface it.
        process.stderr.write(
          `WARNING: ${ws} self-test output could not be parsed (${r.error}) — ` +
          `reporting 0 pass/0 fail, which may mean the workspace isn't built ` +
          `(run \`npm install && npm run build --workspace=${ws}\`) rather ` +
          `than that it has no tests.\n`
        );
      }
      components.push({
        name: `${ws} self-test`,
        kind: "npm-self-test",
        cmd: `npm test --workspace=${ws}`,
        ...r,
        notes: r.error ? `ERROR: ${r.error}` : `${r.pass}/${r.pass + r.fail} PASS`,
      });
    } catch (e) {
      process.stderr.write(`WARNING: ${ws} self-test could not be run at all (${e.message.slice(0, 100)}) — reporting 0 pass/0 fail.\n`);
      components.push({ name: `${ws} self-test`, cmd: `npm test --workspace=${ws}`, pass: 0, fail: 0, notes: `ERROR: ${e.message.slice(0, 100)}` });
    }
  }

  // 3. e2e-* drivers — auto-discovered via readdirSync on executor/examples/.
  //    A new e2e-XXX/drive-run.mjs is picked up automatically, no script edit
  //    needed (per ADR-0029 Q2 follow-up). Drivers that produce no OK/FAIL
  //    lines (narrative-only demos like e2e-membership-bug) are flagged as
  //    "no-assertions" and emit a WARNING so the next contributor adding a
  //    narrative-only script knows to either add assertions or document
  //    why it has none (per ADR-0029 Q3 follow-up).
  const e2eDir = join(REPO_ROOT, "executor", "examples");
  let e2eDirs = readdirSync(e2eDir, { withFileTypes: true })
    .filter(d => d.isDirectory() && d.name.startsWith("e2e-"))
    .map(d => d.name)
    .sort();
  let e2ePass = 0, e2eFail = 0, e2eRunnable = 0, e2eNoAssertions = 0;
  const noAssertionDrivers = [];
  const failedDrivers = [];
  for (const dir of e2eDirs) {
    const scriptPath = join("executor", "examples", dir, "drive-run.mjs");
    const fullPath = join(REPO_ROOT, scriptPath);
    if (!existsSync(fullPath)) continue;
    try {
      const r = runE2eDriver(scriptPath);
      e2eRunnable++;
      e2ePass += r.pass;
      e2eFail += r.fail;
      if (r.status === "no-assertions") {
        e2eNoAssertions++;
        noAssertionDrivers.push(dir);
      }
      if (r.status === "fail") {
        failedDrivers.push({ dir, pass: r.pass, fail: r.fail });
      }
    } catch (e) {
      // Skip silently — driver not runnable
    }
  }
  // Emit WARNINGs for no-assertion drivers so they're visible in the
  // script output (and would be visible in CI logs too).
  if (noAssertionDrivers.length > 0) {
    process.stderr.write(
      `WARNING: ${noAssertionDrivers.length} e2e driver(s) produced no OK/FAIL lines — ` +
      `counted as "narrative-only" (0 pass / 0 fail). ` +
      `If a driver is supposed to have assertions, this means its ` +
      `output format doesn't match the "  OK  " / "  FAIL  " pattern ` +
      `and the count is wrong. Drivers: ${noAssertionDrivers.join(", ")}\n`
    );
  }
  if (failedDrivers.length > 0) {
    process.stderr.write(
      `WARNING: ${failedDrivers.length} e2e driver(s) emitted FAILED lines — ` +
      `counts include these fails. Drivers: ${failedDrivers.map(d => `${d.dir} (${d.fail} fail)`).join(", ")}\n`
    );
  }
  components.push({
    name: `e2e-* drivers (${e2eRunnable} runnable, ${e2eNoAssertions} narrative-only)`,
    kind: "e2e-driver",
    cmd: "node executor/examples/e2e-*/drive-run.mjs",
    pass: e2ePass,
    fail: e2eFail,
    notes: noAssertionDrivers.length > 0
      ? `${e2eRunnable - e2eNoAssertions}/${e2eRunnable} drivers PASS with assertions; narrative-only: ${noAssertionDrivers.join(", ")}`
      : `${e2eRunnable - e2eNoAssertions}/${e2eRunnable} drivers PASS with assertions`,
  });

  // 5. chat-output validator — one entry per file, plus an aggregate row
  const chatDir = join(REPO_ROOT, "scripts", "test-responses");
  let chatFiles = readdirSync(chatDir)
    // README.md documents the fixtures, it is not itself a chat-output
    // fixture — including it here was a real bug (found while fixing
    // this file's error-masking, see ADR-0029): it always fails
    // validate-chat-output.mjs (no ```aiecp:* blocks) and, since that
    // failure mode emits no "Results:" line, silently counted as a
    // parse error indistinguishable from a real fixture problem.
    .filter(f => f.endsWith(".md") && f !== "README.md")
    .sort();
  let chatPass = 0, chatFail = 0;
  const chatErrors = [];
  for (const f of chatFiles) {
    const filePath = join("scripts", "test-responses", f);
    try {
      const r = runChatValidator(filePath);
      if (r.error) {
        chatErrors.push(f);
      } else {
        chatPass += r.pass;
        chatFail += r.fail;
      }
    } catch (e) {
      chatErrors.push(f);
    }
  }
  if (chatErrors.length > 0) {
    // Same masking risk as above: a fixture whose output couldn't be
    // parsed (e.g. a missing dependency like `ajv` — see
    // evaluations/README.md prerequisites) was previously dropped
    // silently, understating the total instead of surfacing the gap.
    process.stderr.write(
      `WARNING: ${chatErrors.length} chat-output fixture(s) could not be validated ` +
      `(parse/run error) and are excluded from the pass/fail count below — this ` +
      `understates the real total rather than meaning those fixtures have no ` +
      `assertions. Run \`node scripts/validate-chat-output.mjs <file>\` directly ` +
      `on each to see the actual error. Files: ${chatErrors.join(", ")}\n`
    );
  }
  components.push({
    name: "validate-chat-output.mjs (test-responses/)",
    kind: "chat-validator",
    cmd: "node scripts/validate-chat-output.mjs <file>",
    pass: chatPass,
    fail: chatFail,
    notes: chatErrors.length > 0
      ? `${chatErrors.length} fixture(s) errored and are excluded from this count — see stderr; ` +
        `otherwise see scripts/test-responses/README.md for intentional-fail regression cases`
      : "see scripts/test-responses/README.md for which fixtures are intentional-fail regression cases",
  });

  return components;
}

// ---- output formatters ----

function totalPass(c) { return c.reduce((s, x) => s + (x.pass || 0), 0); }
function totalFail(c) { return c.reduce((s, x) => s + (x.fail || 0), 0); }

function renderSummary(components) {
  const pass = totalPass(components);
  const fail = totalFail(components);
  return `Total: ${pass} pass + ${fail} fail across ${components.length} components`;
}

function renderMarkdownTable(components) {
  const lines = [];
  lines.push("<!-- AUTO-GENERATED by `node scripts/count-assertions.mjs --write`. DO NOT EDIT by hand. -->");
  lines.push("<!-- Last regenerated: " + new Date().toISOString() + " -->");
  lines.push("");
  lines.push("| Component | Run command | Pass | Fail | Notes |");
  lines.push("|---|---|---|---|---|");
  for (const c of components) {
    const notes = c.notes || c.error || "";
    lines.push(`| \`${c.name}\` | \`${c.cmd}\` | ${c.pass || 0} | ${c.fail || 0} | ${notes} |`);
  }
  const p = totalPass(components);
  const f = totalFail(components);
  lines.push(`| **Total** | | **${p}** | **${f}** | ${renderSummary(components)} |`);
  // Trailing newline so the table ends with a newline (matches the
  // STATUS.md convention where a blank line follows the table before
  // the END AUTO-GENERATED marker).
  return lines.join("\n") + "\n";
}

// ---- main ----

const args = new Set(process.argv.slice(2));
const wantJson = args.has("--json");
const wantTable = args.has("--table");
const wantWrite = args.has("--write");
const wantCheck = args.has("--check");   // CI mode: fail if STATUS.md table is stale

const components = collectAll();

if (wantJson) {
  console.log(JSON.stringify({
    generated_at: new Date().toISOString(),
    components,
    total_pass: totalPass(components),
    total_fail: totalFail(components),
  }, null, 2));
} else if (wantTable) {
  console.log(renderMarkdownTable(components));
} else if (wantWrite) {
  const table = renderMarkdownTable(components);
  const statusPath = join(REPO_ROOT, "STATUS.md");
  let status = readFileSync(statusPath, "utf-8");

  // Replace the auto-generated block. The block is delimited by:
  //   <!-- AUTO-GENERATED by `node scripts/count-assertions.mjs --write`. DO NOT EDIT by hand. -->
  //   ... table ...
  //   <!-- END AUTO-GENERATED -->
  // If the END marker doesn't exist, we add it.
  const startMarker = "<!-- AUTO-GENERATED by `node scripts/count-assertions.mjs --write`. DO NOT EDIT by hand. -->";
  const endMarker = "<!-- END AUTO-GENERATED -->";

  const startIdx = status.indexOf(startMarker);
  if (startIdx === -1) {
    // No existing block — append it after the assertion-breakdown header
    const headerNeedle = "**Assertion breakdown (every component actually run";
    const headerIdx = status.indexOf(headerNeedle);
    if (headerIdx === -1) {
      console.error("Could not find 'Assertion breakdown' header in STATUS.md — refusing to write");
      process.exit(1);
    }
    // Find the next blank line after the header
    const afterHeader = status.indexOf("\n", headerIdx);
    const insertPoint = afterHeader + 1;
    const newBlock = `\n${table}\n${endMarker}\n\n`;
    status = status.slice(0, insertPoint) + newBlock + status.slice(insertPoint);
  } else {
    // Existing block — replace between markers.
    // `table` already ends with a trailing newline (see renderMarkdownTable).
    let endIdx = status.indexOf(endMarker, startIdx);
    if (endIdx === -1) {
      endIdx = status.length;
    }
    status = status.slice(0, startIdx) + table + endMarker + status.slice(endIdx + endMarker.length);
  }

  writeFileSync(statusPath, status);
  console.log(`Updated STATUS.md assertion table. Total: ${totalPass(components)} pass + ${totalFail(components)} fail`);

  const passes = totalPass(components);

  // Auto-sync package.json
  const pkgPath = join(REPO_ROOT, "package.json");
  const pkg = JSON.parse(readFileSync(pkgPath, "utf-8"));
  pkg.description = pkg.description.replace(/\d+\s+assertions passing/, `${passes} assertions passing`);
  writeFileSync(pkgPath, JSON.stringify(pkg, null, 2) + "\n");

  // Auto-sync README.md
  const readmePath = join(REPO_ROOT, "README.md");
  let readme = readFileSync(readmePath, "utf-8");
  readme = readme.replace(/assertions-\d+-brightgreen/, `assertions-${passes}-brightgreen`);
  writeFileSync(readmePath, readme);

  // Auto-sync RELEASE_NOTES.md
  const relPath = join(REPO_ROOT, "RELEASE_NOTES.md");
  let rel = readFileSync(relPath, "utf-8");
  rel = rel.replace(/\|\s*Passing Assertions\s*\|\s*\d+\s*\|/, `| Passing Assertions | ${passes} |`);
  writeFileSync(relPath, rel);

  console.log(`Auto-synced assertion counts (${passes}) across package.json, README.md, and RELEASE_NOTES.md.`);
  console.log("");
  console.log(renderMarkdownTable(components));
} else if (wantCheck) {
  // CI mode: compute the table fresh and compare against what's in STATUS.md.
  // Exit 0 if they match, exit 1 if STATUS.md is stale (table drift detected).
  const freshTable = renderMarkdownTable(components);
  const statusPath = join(REPO_ROOT, "STATUS.md");
  const status = readFileSync(statusPath, "utf-8");

  const startMarker = "<!-- AUTO-GENERATED by `node scripts/count-assertions.mjs --write`. DO NOT EDIT by hand. -->";
  const endMarker = "<!-- END AUTO-GENERATED -->";
  const startIdx = status.indexOf(startMarker);
  let endIdx = startIdx === -1 ? -1 : status.indexOf(endMarker, startIdx);

  if (startIdx === -1 || endIdx === -1) {
    console.error("FAIL: STATUS.md does not contain the AUTO-GENERATED block.");
    console.error("Run `npm run count-assertions -- --write` to insert it.");
    process.exit(1);
  }

  // Extract the current table from STATUS.md (between markers).
  // Normalize the timestamp comment line, since that will always differ
  // between a fresh run and the stored version.
  const tsRegex = /<!-- Last regenerated: [^>]+ -->/;
  const currentTable = status.slice(startIdx, endIdx).replace(
    tsRegex,
    "<!-- Last regenerated: TIMESTAMP -->"
  );
  const freshTableNormalized = freshTable.replace(
    tsRegex,
    "<!-- Last regenerated: TIMESTAMP -->"
  );

  if (currentTable === freshTableNormalized) {
    console.log("OK: STATUS.md assertion table is up to date.");
    console.log(`Total: ${totalPass(components)} pass + ${totalFail(components)} fail`);
    process.exit(0);
  } else {
    console.error("FAIL: STATUS.md assertion table is stale.");
    console.error("");
    console.error("Current (in STATUS.md) — length " + currentTable.length + ":");
    console.error(JSON.stringify(currentTable));
    console.error("");
    console.error("Fresh (from running all harnesses) — length " + freshTableNormalized.length + ":");
    console.error(JSON.stringify(freshTableNormalized));
    console.error("");
    // Find first diff position
    for (let i = 0; i < Math.max(currentTable.length, freshTableNormalized.length); i++) {
      if (currentTable[i] !== freshTableNormalized[i]) {
        console.error(`First diff at index ${i}:`);
        console.error(`  current: ${JSON.stringify(currentTable.slice(Math.max(0, i - 20), i + 20))}`);
        console.error(`  fresh:   ${JSON.stringify(freshTableNormalized.slice(Math.max(0, i - 20), i + 20))}`);
        break;
      }
    }
    console.error("");
    console.error("Run `npm run count-assertions -- --write` to regenerate.");
    process.exit(1);
  }
} else {
  // Default: print summary + table
  console.log("=== AIECP assertion count ===");
  console.log(`Generated: ${new Date().toISOString()}`);
  console.log("");
  console.log(renderSummary(components));
  console.log("");
  console.log(renderMarkdownTable(components));
  console.log("");
  console.log("To update STATUS.md with this table: npm run count-assertions -- --write");
  console.log("To get JSON output:                  npm run count-assertions -- --json");
}
